import { useState } from "react";

const Home = () => {

    let name = useState;
    function handleClick() {
        name = (name === "me") ? "Escape" : "me";
        console.log("Name changed to ", name)
    }
    return ( 
        <div className="home">
            <h2>HomePage</h2>
            <p>{name}</p>
            <button onClick={handleClick}>Update name</button>
        </div>
     );
}
 
export default Home;
